from sympy import symbols, integrate, diff, simplify, expand, sqrt, exp, log, sin, cos, asin, atan, Abs, oo, Rational

x = symbols("x", real=True)
u = symbols("u")
z = symbols("z", positive=True)

def parts(kind, a, k):
    dv = [exp(k*x), cos(k*x), sin(k*x)][kind - 1]
    U, v = x + a, integrate(dv, x)
    answer = U*v - integrate(v * diff(U, x), x)
    print(f"  u = {U}, dv = {dv} dx, so du = dx and v = {v}")
    print(f"  uv - (integral of v du) = {answer} + C, check: {simplify(diff(answer, x) - U*dv) == 0}")

def trig(m, n):
    if n % 2 == 1:
        g = u**m * (1 - u**2)**((n - 1) // 2)
        print(f"  save one cos x, u = sin x: the integral of {g} du")
        F = integrate(expand(g), u).subs(u, sin(x))
    elif m % 2 == 1:
        g = -u**n * (1 - u**2)**((m - 1) // 2)
        print(f"  save one sin x, u = cos x, sin x dx = -du: the integral of {g} du")
        F = integrate(expand(g), u).subs(u, cos(x))
    else:
        print("  both powers even: no factor to save, so use the half-angle formulas")
        F = integrate(sin(x)**m * cos(x)**n, x)
    print(f"  {F} + C")

def cover(p, q, a, b):
    A, B = (p*a + q) / (a - b), (p*b + q) / (b - a)
    print(f"  cover up {x - a} and put x = {a} into ({p*x + q})/({x - b}): A = {A}")
    print(f"  cover up {x - b} and put x = {b} into ({p*x + q})/({x - a}): B = {B}")
    print(f"  {A*log(Abs(x - a)) + B*log(Abs(x - b))} + C")

def trigsub(shape, a):
    if shape == 1:
        f, F = 1 / sqrt(a**2 - x**2), asin(x / a)
        print(f"  x = {a} sin(theta), dx = {a} cos(theta) dtheta, the root = {a} cos(theta): the integral of dtheta")
    elif shape == 2:
        f, F = 1 / (a**2 + x**2), atan(x / a) / a
        print(f"  x = {a} tan(theta), dx = {a} sec(theta)^2 dtheta, {a**2} + x^2 = {a**2} sec(theta)^2: the integral of dtheta/{a}")
    else:
        f, F = sqrt(a**2 - x**2), a**2 * asin(x / a) / 2 + x * sqrt(a**2 - x**2) / 2
        print(f"  x = {a} sin(theta): the integral of {a**2} cos(theta)^2 dtheta = ({a**2}/2)(theta + sin(theta) cos(theta))")
    print(f"  back with the triangle: {F} + C, check: {simplify(diff(F, x) - f) == 0}")

def pint(p, near_zero):
    if near_zero == 0:
        print(f"  1/x^p with p = {p}, from 1 to infinity: far out it converges only for p > 1")
        value = integrate(z**-p, (z, 1, oo))
    else:
        print(f"  1/x^p with p = {p}, from 0 to 1: near 0 it converges only for p < 1")
        value = integrate(z**-p, (z, 0, 1))
    if value == oo:
        print("  so it diverges")
    else:
        print(f"  so it converges, to {value}")

def run(kind, nums):
    if kind == "parts":
        parts(int(nums[0]), nums[1], nums[2])
    elif kind == "trig":
        trig(int(nums[0]), int(nums[1]))
    elif kind == "cover":
        cover(nums[0], nums[1], nums[2], nums[3])
    elif kind == "trigsub":
        trigsub(int(nums[0]), nums[1])
    else:
        pint(nums[0], nums[1])

problems = [("parts", [1, 0, 2]), ("trig", [3, 2]), ("cover", [5, -1, 1, -1]), ("trigsub", [2, 4]), ("pint", ["1/3", 1]),
    ("trig", [2, 2]), ("parts", [2, 1, 3]), ("pint", [1, 0]), ("trigsub", [3, 3]), ("cover", [0, 1, 0, 2])]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Rational(v) for v in nums]
    print(f"Problem {i + 1}: {kind} {nums}")
    run(kind, nums)

