from sympy import symbols, integrate, diff, simplify, factor, expand, apart, solve, limit, sqrt, exp, log, sin, cos, atan, Abs, oo, factorial, Rational

x = symbols("x", real=True)
t = symbols("t", positive=True)

def tabular(n, k):
    D = [x**n]
    while D[len(D) - 1] != 0:
        D.append(diff(D[len(D) - 1], x))
    I = [exp(k*x)]
    for i in range(len(D) - 1):
        I.append(integrate(I[len(I) - 1], x))
    print(f"  D: {D}, I: {I[1:]}")
    F = sum((-1)**i * D[i] * I[i + 1] for i in range(len(D) - 1))
    print(f"  diagonals with signs +, -, +, ...: {factor(F)} + C")

def loop(kind, a, b):
    if kind == 1:
        known = exp(a*x)*sin(b*x)/a - b*exp(a*x)*cos(b*x)/a**2
        f = exp(a*x)*sin(b*x)
    else:
        known = exp(a*x)*cos(b*x)/a + b*exp(a*x)*sin(b*x)/a**2
        f = exp(a*x)*cos(b*x)
    print(f"  two rounds with u the trig factor: I = {known} - ({b**2 / a**2}) I")
    I = simplify(known / (1 + b**2 / a**2))
    print(f"  so ({1 + b**2 / a**2}) I = that, and I = {I} + C, check: {simplify(diff(I, x) - f) == 0}")

def repeated(p, q, a, b):
    f = (p*x + q) / ((x - a)**2 * (x - b))
    print(f"  {f} = {apart(f, x)}")
    print(f"  integrate each piece: {integrate(apart(f, x), x)} + C")

def tail(n, k):
    F = integrate(t**n * exp(-k*t), (t, 0, x))
    print(f"  by parts, the integral from 0 to x is {expand(F)}")
    print(f"  as x grows the exponential wins: the limit is {limit(F, x, oo)} = {n}!/{k}^{n + 1} = {factorial(n) / k**(n + 1)}")

def quad(b, c):
    D = b**2 - 4*c
    print(f"  {x**2 + b*x + c} has discriminant {D}")
    if D < 0:
        h = sqrt(c - b**2 / 4)
        print(f"  complete the square: {(x + b/2)**2 + c - b**2/4}, then the arctan: {atan((x + b/2) / h) / h} + C")
    elif D > 0:
        r = sorted(solve(x**2 + b*x + c, x))
        print(f"  two roots {r}: partial fractions, {log(Abs(x - r[1])) / (r[1] - r[0]) - log(Abs(x - r[0])) / (r[1] - r[0])} + C")
    else:
        print(f"  a perfect square {(x + b/2)**2}: the power rule, {-1 / (x + b/2)} + C")

def run(kind, nums):
    if kind == "tabular":
        tabular(int(nums[0]), nums[1])
    elif kind == "loop":
        loop(int(nums[0]), nums[1], nums[2])
    elif kind == "repeated":
        repeated(nums[0], nums[1], nums[2], nums[3])
    elif kind == "tail":
        tail(int(nums[0]), nums[1])
    else:
        quad(nums[0], nums[1])

problems = [("tabular", [2, 3]), ("loop", [1, 1, 2]), ("repeated", [0, 1, 0, 1]), ("tail", [1, 2]), ("quad", [4, 13]),
    ("quad", [2, -3]), ("tabular", [3, -1]), ("loop", [2, 2, 1]), ("quad", [-6, 9]), ("repeated", [3, -1, 1, -1]), ("tail", [2, 1])]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Rational(v) for v in nums]
    print(f"Problem {i + 1}: {kind} {nums}")
    run(kind, nums)

