x = symbols("x", real=True)
z = symbols("z", positive=True)

def divide(b, c, a):
    r = a**2 + a*b + c
    print(f"  ({x**2 + b*x + c})/({x - a}) is improper: divide first, quotient {x + a + b}, remainder {r}")
    print(f"  {x**2 / 2 + (a + b)*x + r*log(Abs(x - a))} + C")
    print(f"  the trap, the cover-up without dividing: {r*log(Abs(x - a))} + C, which misses {x**2 / 2 + (a + b)*x}")

def pcheck(p, where):
    far, near = integrate(z**-p, (z, 1, oo)), integrate(z**-p, (z, 0, 1))
    if where == 1:
        print(f"  1/x^p with p = {p} from 1 to infinity: far out it needs p > 1, and the value is {far}")
    elif where == 2:
        print(f"  1/x^p with p = {p} from 0 to 1: near 0 it needs p < 1, and the value is {near}")
    else:
        print(f"  1/x^p with p = {p} from 0 to infinity: split at 1, pieces {near} and {far}")
        print("  it diverges, since no p is both less than 1 and greater than 1")

def middle(c, a, b, p):
    print(f"  1/|{x - c}|^({p}) blows up at {c}, inside [{a}, {b}]: split there")
    if p < 1:
        left, right = (c - a)**(1 - p) / (1 - p), (b - c)**(1 - p) / (1 - p)
        print(f"  both pieces are p-integrals with p = {p} < 1: {left} + {right} = {left + right}")
    else:
        print(f"  each piece is a p-integral with p = {p} >= 1 near the asymptote: it diverges")

def compare(p, c):
    print(f"  1/(x^({p}) + {c}) <= 1/x^({p}) for x >= 1, a bigger bottom")
    if p > 1:
        print(f"  1/x^({p}) converges, since p > 1, so the smaller one converges too")
    else:
        print(f"  the trap: smaller than the divergent 1/x^({p}) proves nothing")
        print(f"  instead, x^({p}) + {c} <= {1 + c}x^({p}) for x >= 1, so it's at least 1/({1 + c}x^({p})), which diverges")

def run(kind, nums):
    if kind == "divide":
        divide(nums[0], nums[1], nums[2])
    elif kind == "pcheck":
        pcheck(nums[0], nums[1])
    elif kind == "middle":
        middle(nums[0], nums[1], nums[2], nums[3])
    else:
        compare(nums[0], nums[1])

